INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43361, 'Jeremiah 46:21', 'Jeremiah', 46, 21, 'د مِصر د کرايه فوجيان لکه د کمزورو سخو په شان دى. هغوئ به هم په يو ځائ راوګرځى او په شريکه به وتښتى، هغوئ به په خپل ځائ باندې ونۀ دريږى. ځکه چې په هغوئ د تباهۍ او افت ورځ راروانه ده، دا د هغوئ دپاره د سزا ورکولو ورځ ده.', 'د مصر د کرایه فوجیان لکه د کمزورو سخو په شان دی. هغوی به هم په یو جای راوګرجی او په شریکه به وتشتی، هغوی به په خپل جای باندې ونۀ دریزی. جکه چې په هغوی د تباهی او افت ورج راروانه ده، دا د هغوی دپاره د سزا ورکولو ورج ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43362, 'Jeremiah 46:22', 'Jeremiah', 46, 22, 'مِصر به لکه د مار په شان کشار وکړى او په وروستو به وتښتى کله چې د دشمن فوج ورباندې حمله وکړى، هغوئ به د دوئ خلاف تبر په لاس راشى او په دوئ به داسې حمله وکړى لکه څنګه چې يو سړے ونې وهى.', 'مصر به لکه د مار په شان کشار وکری او په وروستو به وتشتی کله چې د دشمن فوج ورباندې حمله وکری، هغوی به د دوی خلاف تبر په لاس راشی او په دوی به داسې حمله وکری لکه چنګه چې یو سرے ونې وهی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43363, 'Jeremiah 46:23', 'Jeremiah', 46, 23, 'مالِک خُدائ فرمائى چې، هغوئ به د مِصر خلق د ځنګلى ونو په شان ووهى، ځکه چې د هغوئ شمېر د مُولخانو نه هم ډېر بې‌شمېره دے.', 'مالک خدای فرمایی چې، هغوی به د مصر خلق د جنګلی ونو په شان ووهی، جکه چې د هغوی شمېر د مولخانو نه هم دېر بې‌شمېره دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43364, 'Jeremiah 46:24', 'Jeremiah', 46, 24, 'د مِصر خلق به وشرميږى، او د شمال خلقو ته به حواله کړے شى.“', 'د مصر خلق به وشرمیزی، او د شمال خلقو ته به حواله کرے شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43365, 'Jeremiah 46:25', 'Jeremiah', 46, 25, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، ”زۀ به امون د مِصر د تيبس معبود او د مِصر نورو معبودانو ته سزا ورکړم. زۀ به د مِصر بادشاهانو او فِرعون ته او هغوئ ټولو ته سزا ورکړم څوک چې په هغۀ يقين کوى.', 'مالک خدای رب الافواج د بنی اسراییلو خدای پاک فرمایی، ”زۀ به امون د مصر د تیبس معبود او د مصر نورو معبودانو ته سزا ورکرم. زۀ به د مصر بادشاهانو او فرعون ته او هغوی تولو ته سزا ورکرم چوک چې په هغۀ یقین کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43366, 'Jeremiah 46:26', 'Jeremiah', 46, 26, 'مالِک خُدائ فرمائى چې، زۀ به هغوئ هغه خلقو ته حواله کړم څوک چې دوئ وژل غواړى، نبوکدنضر د بابل بادشاه او د هغۀ آفسرانو ته. خو وروستو به مِصر کښې د وړاندې په شان خلق بيا آباد شى. دا مالِک خُدائ فرمائى.“', 'مالک خدای فرمایی چې، زۀ به هغوی هغه خلقو ته حواله کرم چوک چې دوی وژل غواری، نبوکدنضر د بابل بادشاه او د هغۀ افسرانو ته. خو وروستو به مصر کشې د وراندې په شان خلق بیا اباد شی. دا مالک خدای فرمایی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43367, 'Jeremiah 46:27', 'Jeremiah', 46, 27, '”اے زما خِدمتګاره يعقوبه مۀ يرېږه، اے اِسرائيله مۀ يرېږه. زۀ به تاسو د هغه لرې مُلک نه دوباره خپلو کورونو ته راولم، چرته چې تاسو جلاوطن شوى يئ. ستا اولاد به زۀ خپلو کورونو ته د جلاوطنۍ نه واپس راولم. يعقوب به دوباره خپل مُلک ته راشى او په امن او سکون سره به ژوند کوى، او تاسو به څوک هم نۀ يروى.', '”اے زما خدمتګاره یعقوبه مۀ یرېزه، اے اسراییله مۀ یرېزه. زۀ به تاسو د هغه لرې ملک نه دوباره خپلو کورونو ته راولم، چرته چې تاسو جلاوطن شوی یی. ستا اولاد به زۀ خپلو کورونو ته د جلاوطنی نه واپس راولم. یعقوب به دوباره خپل ملک ته راشی او په امن او سکون سره به ژوند کوی، او تاسو به چوک هم نۀ یروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43368, 'Jeremiah 46:28', 'Jeremiah', 46, 28, 'مالِک خُدائ فرمائى چې، اے زما خِدمتګاره يعقوبه مۀ يرېږه، ځکه زۀ تا سره يم. زۀ به په پوره توګه هغه قومونه تباه کړم کومو ته چې تاسو ما جلا وطن کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به ستاسو په اِنصاف سره تنبيه وکړم، زۀ به تاسو بې‌سزا نۀ پرېږدم.“', 'مالک خدای فرمایی چې، اے زما خدمتګاره یعقوبه مۀ یرېزه، جکه زۀ تا سره یم. زۀ به په پوره توګه هغه قومونه تباه کرم کومو ته چې تاسو ما جلا وطن کری وی، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به ستاسو په انصاف سره تنبیه وکرم، زۀ به تاسو بې‌سزا نۀ پرېزدم.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_46_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43369, 'Proverbs 10:1', 'Proverbs', 10, 1, 'دا د سلیمان متلونه دي.', 'دا د سلیمان متلونه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_001.mp3', 'https://drive.google.com/file/d/1n_njc_fHyLZp7HjIY8jZ0G49dod_UAUD/preview', 1761237842, 1761237842),
(43370, 'Proverbs 10:2', 'Proverbs', 10, 2, 'هغه دولت چې د ناروا لارې تر‌لاسه کیږي ګټه نه لري خو صداقت انسان له مرګ نه ژغوري.', 'هغه دولت چې د ناروا لارې تر‌لاسه کیزی ګته نه لری خو صداقت انسان له مرګ نه ژغوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_002.mp3', 'https://drive.google.com/file/d/1M2kJaJLbbrtjwtDuQmvxNLbyXqAV6XC9/preview', 1761237842, 1761237842),
(43371, 'Proverbs 10:3', 'Proverbs', 10, 3, 'څښتن نېک انسان لوږې ته نه پرېږدي خو د بدکارانو غوښتنې شنډوي.', 'چشتن نېک انسان لوزې ته نه پرېزدی خو د بدکارانو غوشتنې شندوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_003.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1ab1EBJ2PyaqmnmxNEBq-_p-1AvDFDJB3&export=download', 1761237842, 1761237842),
(43372, 'Proverbs 10:4', 'Proverbs', 10, 4, 'بېکاره لاسونه انسان خواروي خو زحمت کښه لاسونه انسان شتمن کوي.', 'بېکاره لاسونه انسان خواروی خو زحمت کشه لاسونه انسان شتمن کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_004.mp3', 'https://drive.google.com/file/d/16Mn6fgY-n-VxnF_5TOCXOnFjBcfzWflg/preview', 1761237842, 1761237842),
(43373, 'Proverbs 10:5', 'Proverbs', 10, 5, 'هوښیار زوی په اوړي کې خپل فصل راټولوي خو د لو په وخت کې ویده شوی زوی شرم راوړي.', 'هوشیار زوی په اوری کې خپل فصل راتولوی خو د لو په وخت کې ویده شوی زوی شرم راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_005.mp3', 'https://drive.google.com/uc?id=1gHVxYWaePhmpOQB0RZJdYV3_pii-ojgs&export=download', 1761237842, 1761237842),
(43374, 'Proverbs 10:6', 'Proverbs', 10, 6, 'برکت د نېک سړي د سر تاج دی خو د بدکارانو ظلم د هغوی په خوله پرده اچوي.', 'برکت د نېک سری د سر تاج دی خو د بدکارانو ظلم د هغوی په خوله پرده اچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_006.mp3', 'https://drive.google.com/file/d/1XjEOBPbEOb7sNJLwk8qGUg-SiKZ2aa9_/preview', 1761237842, 1761237842),
(43375, 'Proverbs 10:7', 'Proverbs', 10, 7, 'د نېک سړي یادول د برکت سبب کیږي خو د بدکارانو د نوم نه زړه بدیږي.', 'د نېک سری یادول د برکت سبب کیزی خو د بدکارانو د نوم نه زره بدیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_007.mp3', 'https://drive.google.com/file/d/1NNCJPGQibgO8Y79Q68leivhpDHZh-F4t/preview', 1761237842, 1761237842),
(43376, 'Proverbs 10:8', 'Proverbs', 10, 8, 'د حکمت خاوند حکمونه مني خو د جاهل انسان خپله ژبه بلا ده.', 'د حکمت خاوند حکمونه منی خو د جاهل انسان خپله ژبه بلا ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_008.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1Nq9O9hkGZna4BPi-MiTnec2CVUDGCx23&export=download', 1761237842, 1761237842),
(43377, 'Proverbs 10:9', 'Proverbs', 10, 9, 'څوک چې خپل ژوند په صداقت تېروي ډاډه ګرځي خو د کږو لارو خاوند به رسوا شي.', 'چوک چې خپل ژوند په صداقت تېروی داده ګرجی خو د کزو لارو خاوند به رسوا شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_009.mp3', 'https://drive.google.com/file/d/1xFVm3UoCmRaDbPEJ-UefkPguL692mTDX/preview', 1761237842, 1761237842),
(43378, 'Proverbs 10:10', 'Proverbs', 10, 10, 'څوک چې سترګې وهي دردونه جوړوي او د جاهل انسان خپله ژبه بلا ده.', 'چوک چې سترګې وهی دردونه جوروی او د جاهل انسان خپله ژبه بلا ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_010.mp3', 'https://drive.google.com/file/d/1FhdKPmCC0dIWooB6WEbvpenVkJYyXadr/preview', 1761237842, 1761237842),
(43379, 'Proverbs 10:11', 'Proverbs', 10, 11, 'د نېک انسان خوله د ژوند سرچینه ده خو د بدکارانو خوله په ظلم پرده اچوي.', 'د نېک انسان خوله د ژوند سرچینه ده خو د بدکارانو خوله په ظلم پرده اچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_011.mp3', 'https://drive.google.com/file/d/1WbDar2sW0MWgaXDHkeqDx42ehfQpxuDu/preview', 1761237842, 1761237842),
(43380, 'Proverbs 10:12', 'Proverbs', 10, 12, 'کرکه جګړو ته لمن وهي خو مینه په ټولو ګناهونو پرده اچوي.', 'کرکه جګرو ته لمن وهی خو مینه په تولو ګناهونو پرده اچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_012.mp3', 'https://drive.google.com/file/d/1V7YdcJCj5XtQ1pxljszGaWtQGvsBvv4Q/preview', 1761237842, 1761237842),
(43381, 'Proverbs 10:13', 'Proverbs', 10, 13, 'حکمت د عقلمن په خبرو کې موندل کیږي خو د ناپوه د ملا دپاره لښته ده.', 'حکمت د عقلمن په خبرو کې موندل کیزی خو د ناپوه د ملا دپاره لشته ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_013.mp3', 'https://drive.google.com/file/d/15gNY27ia8eRTUxMeIcMytYaqfRhGA8de/preview', 1761237842, 1761237842),
(43382, 'Proverbs 10:14', 'Proverbs', 10, 14, 'د حکمت خاوندان خپل علم ذخیره کوي خو د جاهلانو د خولې خبرې بربادي راوړي.', 'د حکمت خاوندان خپل علم ذخیره کوی خو د جاهلانو د خولې خبرې بربادی راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_014.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1rCi1ozgL9Q8rjwSQIl7CSO5jgYkRuzxU&export=download', 1761237842, 1761237842),
(43383, 'Proverbs 10:15', 'Proverbs', 10, 15, 'د شتمن مال دولت د هغه دپاره کلا ده خو غریبي د غریبانو دپاره بلا ده.', 'د شتمن مال دولت د هغه دپاره کلا ده خو غریبی د غریبانو دپاره بلا ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_015.mp3', 'https://drive.google.com/file/d/1LcUKexpSD9uozgYksGOHKpQAuXnk92qT/preview', 1761237842, 1761237842),
(43384, 'Proverbs 10:16', 'Proverbs', 10, 16, 'د نېک انسان انعام ژوندون دی خو د بدکاره انسان ګټه ګناه ده.', 'د نېک انسان انعام ژوندون دی خو د بدکاره انسان ګته ګناه ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_016.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1pvfA3wTVRUheDW_P9iKhYycSwlYvpQlI&export=download', 1761237842, 1761237842),
(43385, 'Proverbs 10:17', 'Proverbs', 10, 17, 'نصیحت منونکی نور خلک د ژوندون په لاره روانوي خو اصلاح نه منونکی نور خلک بې‌لارې کوي.', 'نصیحت منونکی نور خلک د ژوندون په لاره روانوی خو اصلاح نه منونکی نور خلک بې‌لارې کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_017.mp3', 'https://drive.google.com/uc?id=13PWUiGUQu1eMRVfPJQp1J5Z2NJFdxa1Z&export=download', 1761237842, 1761237842),
(43386, 'Proverbs 10:18', 'Proverbs', 10, 18, 'څوک چې په دروغو خپله کرکه پټوي او په نورو تور لګوي، هغه کم‌عقل دی.', 'چوک چې په دروغو خپله کرکه پتوی او په نورو تور لګوی، هغه کم‌عقل دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs010_verse_018.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1EbQY5o8WZWNgLXZBIKaI477eki5KX-tv&export=download', 1761237842, 1761237842),
